window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-gineco-e-obstetricia-med-gin-03"]={"block":"med:med-gineco-e-obstetricia-med-gin-03","label":"MED · MED GIN 03","count":172,"questions":[{"id":"med-gineco-e-obstetricia-med-gin-03-26655","number":"26655","sourceNumber":"26655","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Qual dos músculos ajuda a conter o conteúdo abdominal e pélvico, sustenta a parede\nposterior da vagina e facilita defecação?","options":{"A":"Músculo periforme","B":"Músculo elevador do ânus","C":"Músculo coccígeo","D":"Músculo transverso superficial do períneo","E":"Músculo obturador interno"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-13879","number":"13879","sourceNumber":"13879","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Acerca da anatomia pélvica feminina, assinale a opção correta.","options":{"A":"O ligamento pectíneo ou de Cooper é usado com frequência para a suspensão vaginal e oferece\nvantagem do acesso cirúrgico vaginal.","B":"O forame isquiático maior dá passagem ao feixe neurovascular obturador, que pode ser lesado\ndurante procedimento para tratamento de incontinência urinária.","C":"Os músculos do diafragma urogenital, que reforçam o diafragma pélvico, incluem o piriforme, o\ntransverso do períneo e o iliopsoas.","D":"O diafragma da pelve é uma estrutura fibromuscular de sustentação da pelve e inclui os\nmúsculos levantadores do ânus e o isquiococcigeo.","E":"Os músculos levantadores do ânus são formados pelos músculos pubovaginal, pubouretral,\npuborretal e obturador interno."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-19276","number":"19276","sourceNumber":"19276","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 20 anos de idade procurou o serviço de planejamento familiar para receber\norientação a respeito do uso da pílula anticoncepcional combinada como contraceptivo, já que\nvinha tendo relações sexuais regulares há seis meses. Referia boa tolerância ao medicamento e\nmelhora das cólicas menstruais após iniciar a contracepção. A paciente é portadora de epilepsia,\ncontrolada com fenobarbital. Não faz uso de drogas ilícitas, cigarro ou álcool e na sua família não\nhá casos de câncer,\n\nhipertensão, diabetes, cardiopatia ou trombose. Tanto o exame físico geral quanto o exame\nginecológico nela realizados foram\nconsiderados dentro da normalidade. A partir desse caso clínico,\njulgue o seguinte item. Considerando-se a boa tolerância do organismo ao medicamento, a\npaciente deve continuar o uso do contraceptivo hormonal combinado, que vem apresentando\ncomprovada eficácia do medicamento, pois não consta nenhum dado na história clínica ou no\nexame físico dessa paciente que o contraindique.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-220285","number":"220285","sourceNumber":"220285","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação ao ciclo menstrual, assinale a alternativa INCORRETA:","options":{"A":"O ciclo é dividido em duas fases: folicular e lútea, sendo que a fase folicular começa com o\ninício\nda menstruação e termina no dia anterior ao\naumento do Hormônio Luteinizante (LH) e a fase lútea\ncomeça no dia do pico de LH e termina no início da próxima menstruação.","B":"As concentrações séricas de Hormônio Folículo-Estimulante (FSH) e LH estão diminuindo nesse\nmomento (fase folicular tardia) devido aos efeitos de feedback negativo do estradiol e talvez de\noutros hormônios liberados pelo ovário.","C":"O aumento das concentrações séricas de estradiol resulta na proliferação do endométrio uterino,\nque se torna mais espesso, com um aumento\nno número de glândulas e o desenvolvimento de um\npadrão de \"tripla faixa\" ao ultrassom.","D":"O Hormônio Antimülleriano (HAM) sérico tem sido usado como um potencial marcador de saúde\ne envelhecimento ovariano, secretado por pequenos\nfolículos antrais, se correlaciona com o\nnúmero total desses folículos ovarianos e apresenta grande variabilidade ao longo do ciclo\nmenstrual."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-212985","number":"212985","sourceNumber":"212985","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao papel dos ovários no ciclo menstrual, é correto afirmar:","options":{"A":"Os vários estágios do crescimento folicular, desde folículo primordial ao pré-ovulatório são\ndependentes das gonodotrofinas.","B":"O crescimento folicular ocorre somente na menacme.","C":"O folículo que iniciou seu desenvolvimento deverá, necessariamente, caminhar para ovulação ou\nsofrer atresia.","D":"A progesterona promove a aceleração da maturação folicular por atuação na aromatização.","E":"Todos os folículos ovarianos encontram-se em fase de crescimento, cada um em um estágio,\nnão havendo nenhum em fase de repouso."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-172755","number":"172755","sourceNumber":"172755","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à esteroidogênese ovariana, é CORRETO afirmar que:","options":{"A":"Nos ovários, os androgênios produzidos pelas células da teca são convertidos em estrogênios\nna célula da granulosa por ação da enzima\naromatase.","B":"Nos ovários, os androgênios produzidos pelas células da teca são convertidos em estrogênios\nna célula da granulosa por ação da enzima\n5-alfa-redutase.","C":"Nos ovários, os androgênios produzidos pelas células da granulosa são convertidos em\nestrogênios na célula da teca por ação da enzima aromatase.","D":"Nos ovários, os androgênios produzidos pelas células da granulosa são convertidos em\nestrogênios na célula da teca por ação da enzima 5-alfa-redutase."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-188039","number":"188039","sourceNumber":"188039","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à fisiologia menstrual é correto afirmar:","options":{"A":"na fase pré-ovulatória ocorre o pico de LH com baixa de estradiol e FSH;","B":"na fase folicular o FSH, o estradiol, o LH e a progesterona estão em ascensão;","C":"nas fases folicular e pré-ovulatória, o FSH e o LH estão em ascensão e somente declinam na\nfase lútea após o pico de progesterona;","D":"na fase lútea o FSH e o LH estão decrescentes, o estradiol alto, e ocorre o pico de\nprogesterona;","E":"no período menstrual o estradiol, o LH e a progesterona se encontram em níveis baixos e o FSH\ncrescente."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-88894","number":"88894","sourceNumber":"88894","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Considere as assertivas em relação ao controle neuroendócrino do ciclo menstrual: I. A\nluteólise que ocorre cerca de dois a três dias antes do início da menstruação determina a elevação\ndos níveis de FSH. II. O FSH induz tanto a síntese de receptores de FSH quanto de LH nas células\nda teca-granulosa. III. O FSH é essencial para o recrutamento e para o crescimento dos folículos\novarianos, induzindo à proliferação das células da granulosa. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas I e II.","C":"Apenas I e III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-77554","number":"77554","sourceNumber":"77554","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 15 anos, menarca aos 11 anos, deseja iniciar atividade sexual. Apresenta\nciclos menstruais irregulares. Exame físico\nnormal. Qual(is) dos métodos contraceptivos abaixo\npode (m) ser indicados: I - Condom feminino. II - Ogino-Knauss. III - Anticoncepcional hormonal\noral.","options":{"A":"I apenas.","B":"II e III apenas.","C":"I e III apenas.","D":"I, II e III.","E":"III apenas."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-355618","number":"355618","sourceNumber":"355618","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre fisiologia do ciclo menstrual, podemos afirmar que:","options":{"A":"Pulsos de GnRH de baixa frequência favorecem a secreção de LH","B":"Inibina B é secretada pelas células da teca interna em resposta ao LH","C":"GnRH tem ação positiva sobre a síntese e negativa sobre o armazenamento de LH","D":"Pico de LH precede o pico de estradiol em 12 horas","E":"Folículos pré-antrais têm desenvolvimento independente de FSH"},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-362600","number":"362600","sourceNumber":"362600","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em um ciclo menstrual normal, o pico de LH é precedido por um aumento súbito de:","options":{"A":"Progesterona.","B":"Estradiol.","C":"Inibina A.","D":"GnRH."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-362620","number":"362620","sourceNumber":"362620","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Nas células da teca ovariana, sob efeito do LH, o colesterol é convertido em:","options":{"A":"Estrona.","B":"Estradiol.","C":"Androstenediona.","D":"Progesterona."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-366932","number":"366932","sourceNumber":"366932","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre o efeito estrogênico na resistência vascular periférica, marque a alternativa\ncorreta:","options":{"A":"Os estrogênios têm um efeito vasoconstritor direto, aumentando a resistência vascular\nperiférica.","B":"O efeito estrogênico geralmente reduz a resistência vascular periférica, devido à sua ação\nvasodilatadora.","C":"O estrogênio tem um papel insignificante na modulação da resistência vascular.","D":"Os estrogênios atuam diminuindo a produção de óxido nítrico no endotélio."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-362642","number":"362642","sourceNumber":"362642","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Durante a menacme, o local do ovário responsável pela conversão de androgênio em\nestrogênio é:","options":{"A":"teca interna.","B":"teca externa.","C":"cumulus oophorus.","D":"granulosa."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-330125","number":"330125","sourceNumber":"330125","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ovário é uma estrutura importante do corpo feminino e possui algumas funções. Uma\ndessas funções é:","options":{"A":"Produção de progesterona.","B":"Produção de espermatozoides.","C":"Produção de prolactina.","D":"Fixação do embrião."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-330126","number":"330126","sourceNumber":"330126","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação às fases do ciclo menstrual, é CORRETO afirmar:","options":{"A":"A fase lútea se inicia com a menstruação e vai até a ovulação. Essa fase costuma durar de 10 a\n14 dias, e é marcada por fraqueza e cólica.","B":"Na ovulação, o hormônio LH tem como atividades principais a luteinização das células da\ngranulosa e a síntese de progesterona e prostaglandina dentro do folículo.","C":"A fase folicular se inicia após a ovulação. Ocorre a produção da progesterona que auxilia na\nmanutenção do endométrio até o final do ciclo menstrual ou até a gravidez chegar ao fim.","D":"A gonadotrofina aumenta a atividade de enzimas proteolíticas, que são responsáveis,\njuntamente com as prostaglandinas, pela digestão e rotura da parede folicular."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-330134","number":"330134","sourceNumber":"330134","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O hipotálamo é uma estrutura que mantém importantes relações com a hipófise e\nproduz hormônios que serão liberados na\nneuro-hipófise. São hormônios produzidos no hipotálamo:","options":{"A":"Estrogênio e FSH.","B":"Ocitocina e estrogênio.","C":"ADH e ocitocina.","D":"FSH e ADH."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-321628","number":"321628","sourceNumber":"321628","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Analise a imagem ultrassonográfica a seguir. A via de realização dessa ultrassonografia\ne a fase do ciclo menstrual na qual se\nencontra o útero são, respectivamente,","options":{"A":"a via abdominal e a fase progestagênica.","B":"a via abdominal e a fase estrogênica.","C":"a via endovaginal e a fase progestagênica.","D":"a via endovaginal e a fase estrogênica."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-308222","number":"308222","sourceNumber":"308222","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"No ciclo menstrual normal, espera-se encontrar:","options":{"A":"Fase folicular de cerca de 14 dias, em que há estrogênio em ascensão e baixa de progesterona.","B":"Fase folicular de cerca de 14 dias, com altas concentrações de progesterona e LH.","C":"Fase lútea de 21 dias, com LH e progesterona em altas concentrações.","D":"No ciclo endometrial, a fase secretora, que corresponde ao período entre a menstruação e a\novulação, é caracterizada por aumento da secreção glandular."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-313236","number":"313236","sourceNumber":"313236","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na fisiologia reprodutiva, é correto afirmar","options":{"A":"a secreção de GnRH é contínua","B":"enquanto o corpo lúteo do ciclo anterior definha, diminui a produção lútea de progesterona e\ninibinas","C":"a teoria da dupla célula determina que, com a estimulação de LH, as células ovarianas da\ngranulosa produzam androgênios, que serão\nconvertidos em estrogênios pelas células da teca sob\nestímulo do FSH","D":"a elevação dos níveis de estrogênio produz feedback positivo sobre a secreção hipofisária de\nFSH"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-274443","number":"274443","sourceNumber":"274443","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"À medida que o folículo atinge a fase pré-antral, há maior proliferação da camada\ngranulosa, que passa a sintetizar hormônios. O hormônio que induz ou ativa uma reação de\naromatização é o:","options":{"A":"LH.","B":"FSH.","C":"Estrogênio.","D":"Androgênio."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-285077","number":"285077","sourceNumber":"285077","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 19 anos de idade queixa-se de intensa irritabilidade, alterações abruptas de\nhumor e fome incontrolável nos 7 dias que antecedem cada menstruação. Tem ciclos menstruais\nmensais e regulares. Usa diafragma para contracepção. Não tem antecedentes mórbidos, pessoais\nou familiares, relevantes. Qual é o tratamento mais adequado para o caso?","options":{"A":"Inibidor de prostaglandina.","B":"Inibidor de recaptação de serotonina.","C":"Bromoergocriptina.","D":"Filoestrogênios."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-281846","number":"281846","sourceNumber":"281846","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à produção de esteroides sexuais nos ovários, sabe-se que:","options":{"A":"a inibina B, secretada pelas células tecais em resposta ao FSH, suprime a secreção de FSH pela\nhipófise.","B":"a produção de testosterona é realizada nas células da granulosa, sob ação do FSH, liberado\npela hipófise.","C":"as células tecaluteínicas produzem progesterona, testosterona e estradiol em resposta à ação\ndo FSH.","D":"a aromatização dos androgênios, induzida pelo FSH no ovário, é responsável pela produção de\nestrógenos."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-258210","number":"258210","sourceNumber":"258210","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A fisiologia menstrual é determinada pela sincronia extremamente refinada do eixo\nhipotálamo, hipófise e ovários, que recebe\ninterferência de áreas como o córtex cerebral, adrenais e\ntireoide. Na neurofisiologia do ciclo menstrual,","options":{"A":"o ovário, em resposta à ação das gonadotrofinas, realiza unicamente a foliculogênese, não\nsendo capaz de proceder a esteroidogênese.","B":"a cada ciclo, apenas um folículo ovariano é recrutado.","C":"a hipófise secreta o hormônio liberador de corticotropina (ACTH) e o hormônio liberador de\ntireotropina (TRH).","D":"a partir de comandos do córtex cerebral, o hipotálamo libera o hormônio secretor de\ngonadotrofinas (GnRH) de forma pulsátil coordenada."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-249882","number":"249882","sourceNumber":"249882","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A produção de estrogênios no ovário é feita pelas células:","options":{"A":"Da teca.","B":"Da granulosa.","C":"Do corpo lúteo.","D":"Do interstício."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-254259","number":"254259","sourceNumber":"254259","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A fase lútea do ciclo menstrual é associada ao seguinte padrão endometrial:","options":{"A":"Atrófico.","B":"Proliferativo.","C":"Secretório.","D":"Menstrual."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-247441","number":"247441","sourceNumber":"247441","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"No ciclo menstrual, a elevação dos níveis do FSH (Follicie Stimulating Hormone?) no\nfinal da fase lútea do ciclo anterior tem como função:","options":{"A":"iniciar a menstruação.","B":"recrutamento folicular.","C":"involução do corpo lúteo.","D":"estímulo a produção de progesterona."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-232275","number":"232275","sourceNumber":"232275","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A produção de esteroides sexuais se dá durante o desenvolvimento folicular do ciclo\nmenstrual, quando ocorre a produção nas células da teca e da granulosa, respectivamente, os\nhormônios:","options":{"A":"Androgênios e estrogênios.","B":"Androgênios e progesterona.","C":"Estrogênios e progesterona.","D":"Estrogênios e androgênios."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-229893","number":"229893","sourceNumber":"229893","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Durante a fase lútea do ciclo menstrual, o aspecto histológico do endométrio é\ncaracterizado como:","options":{"A":"Atrófico.","B":"Secretor.","C":"Proliferativo.","D":"Hiperplásico."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-201905","number":"201905","sourceNumber":"201905","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Uma adolescente, que começou a apresentar ciclos menstruais aos 13 anos, hoje os\napresenta menores que 21 dias e com o período menstrual maior que 8 dias. Esses eventos são,\nrespectiva e corretamente, denonimados:","options":{"A":"espaniomenorreia e metrorragia","B":"polimenorragia e metrorreia","C":"polimenorreia e hipermenorreia","D":"menorragia e espaniomenorreia","E":"opsomenorreia e hipermenorragia"},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-216626","number":"216626","sourceNumber":"216626","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ciclo menstrual pode ser dividido em dois segmentos: o ciclo ovariano e o ciclo\nuterino. Considerando, respectivamente, a primeira fase de ambos os ciclos, poderíamos\ndenominá-las de fases:","options":{"A":"Folicular e lútea.","B":"Secretora e folicular.","C":"Proliferativa e secretora.","D":"Folicular e proliferativa."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-216637","number":"216637","sourceNumber":"216637","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O pico de LH durante a metade do ciclo menstrual é o responsável pela ovulação e se\ndeve ao estímulo do hormônio:","options":{"A":"Estradiol.","B":"Estrona.","C":"Estriol.","D":"Progesterona."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-216500","number":"216500","sourceNumber":"216500","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O funcionamento harmonioso do eixo hipotálamo-hipófise-ovário mantém a homeostase\nendócrina feminina. Na ovulação, aproximadamente 24h e 12h antes da postura ovular, há pico dos\nseguintes hormônios:","options":{"A":"LH e estradiol.","B":"Estradiol e LH.","C":"FSH e progesterona.","D":"Progesterona e estradiol."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-217062","number":"217062","sourceNumber":"217062","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre o ciclo menstrual, assinale a alternativa correta.","options":{"A":"O estrogênio produzido pelo ovário estimula a proliferação endometrial por meio de mitoses.","B":"Quanto mais estradiol o ovário produz, menos FSH é liberado pela hipófise.","C":"A ovulação ocorre sob níveis de LH constantemente altos.","D":"A fase secretora do ciclo dura 14 dias; já a fase proliferativa pode ser variável.","E":"O LH estimula as células da teca a produzirem androgênios."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-202711","number":"202711","sourceNumber":"202711","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 35 anos, com queixa de sintomas\n\npré-menstruais intensos, com início há cerca de 10 dias antes da menstruação, que melhoram com\no fluxo menstrual, caracterizados por\nansiedade, depressão, insônia, falta de energia, cansaço e\ndores pelo corpo. Diante deste quadro, o tratamento de escolha é:","options":{"A":"acetato de medroxiprogesterona.","B":"sertralina.","C":"danazol.","D":"noretisterona."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-215421","number":"215421","sourceNumber":"215421","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ciclo menstrual é considerado adequado quando dura de:","options":{"A":"20 a 30 dias.","B":"18 a 35 dias.","C":"18 a 30 dias.","D":"24 a 35 dias."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-215431","number":"215431","sourceNumber":"215431","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Para que ocorra ovulação, o pico do LH é precedido em algumas horas pelo pico de:","options":{"A":"Estradiol","B":"Progesterona","C":"Inibina A","D":"FSH"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-205666","number":"205666","sourceNumber":"205666","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em meninas recém-nascidas, os oócitos encontram-se na:","options":{"A":"Prófase da primeira divisão meiótica.","B":"Metáfase da primeira divisão meiótica.","C":"Anáfase da primeira divisão meiótica.","D":"Telófase da primeira divisão meiótica."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-215376","number":"215376","sourceNumber":"215376","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Dos 7 milhões de folículos primordiais de uma mulher, no menacme o número de\nfolículos que chegará até a fase de ovulação é de aproximadamente:","options":{"A":"5.000","B":"1.500","C":"1.000","D":"400"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-175399","number":"175399","sourceNumber":"175399","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O funcionamento harmonioso do eixo hipotalâmico-hipofisário-ovariano mantém a\nhomeostase endócrina feminina. Na ovulação, aproximadamente 24 e 12 horas antes da postura\novular, há pico dos seguintes hormônios:","options":{"A":"LH e estradiol","B":"estradiol e LH","C":"FSH e progesterona","D":"progesterona e estradiol","E":"FSH e estradiol"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-186421","number":"186421","sourceNumber":"186421","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A liberação clínica do hormônio liberador de gonadotrofinas é imprencindível para\nliberação de gonadotrofinas n(a):","options":{"A":"Hipófise anterior.","B":"Hipotálamo.","C":"Núcleo arqueado.","D":"Ovário."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-186424","number":"186424","sourceNumber":"186424","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O estrogênio produz todos os efeitos abaixo, EXCETO:","options":{"A":"Predominância de células superficiais no epitélio vaginal.","B":"Desvio termogênico: elevação da temperatura corporal basal.","C":"Espessamento da mucosa endometrial.","D":"Efeito samambaia do muco cervical."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-182471","number":"182471","sourceNumber":"182471","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na fisiologia reprodutiva, é correto afirmar","options":{"A":"a secreção de GnRH é contínua","B":"enquanto o corpo lúteo do ciclo anterior definha, diminui a produção lútea de progesterona e\ninibinas","C":"a teoria da dupla célula determina que, com a estimulação de LH, as células ovarianas da\ngranulosa produzam androgênios, que serão convertidos em estrogênios pelas células da teca\nsob estímulo do FSH","D":"a elevação dos níveis de estrogênio produz feedback positivo sobre a secreção hipofisária de\nFSH"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-178822","number":"178822","sourceNumber":"178822","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Referente ao ciclo menstrual, marque a alternativa correta.","options":{"A":"A fase lútea caracteriza-se pela diminuição do FSH e do LH e pelo aumento da produção de\nestrogênio, inicia-se na ovulação e tem seu término no primeiro dia da próxima menstruação.","B":"A fisiologia do ciclo menstrual consiste na interação entre hipotálamo, hipófise e ovários.","C":"Cafeína, álcool, excesso de carboidratos e abacaxi pioram os sintomas da TPM.","D":"Atividade física melhora sintomas físicos e psíquicos, por isso é recomendada a prática de\nexercícios aeróbicos por pelo menos 30 minutos, 3 vezes na semana.","E":"Os inibidores seletivos de receptação de serotonina não devem ser usados em pacientes com a\nsíndrome de tensão pré-menstrual por agravarem os sintomas."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-173588","number":"173588","sourceNumber":"173588","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A síndrome pré-menstrual ocorre com maior frequência em mulheres de 25 a 35 anos,\ne é caracterizada por:","options":{"A":"predominância de sintomas psíquicos e comportamentais que ocorrem no início da fase lútea.","B":"predominância de sintomas físicos que ocorrem antes e depois da menstruação.","C":"sintomas físicos, psíquicos e comportamentais que se iniciam na fase folicular, continuam na\nfase lútea e terminam com a menstrução.","D":"sintomas físicos, psíquicos e comportamentais que se iniciam na fase lútea, podem desaparecer\ncom o fluxo menstrual ou continuar até a fase\nfolicular."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-150778","number":"150778","sourceNumber":"150778","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A puberdade se deve à reativação do eixo hipotálamo-hipofisário que era\ncompletamente ativo durante a vida fetal, mas\nesteve suprimido durante a infância. Em relação aos\neventos que iniciam o desenvolvimento puberal:","options":{"A":"O aparecimento dos caracteres sexuais secundários e as concentrações de LH são menores\ndurante o sono em relação à vigília.","B":"A elevação das gonadotrofinas na puberdade é dependente dos valores de esteroides nas\ngônadas.","C":"O FSH é o primeiro hormônio a aumentar na puberdade e a atividade do LH está diminuída.","D":"A ação sinérgica do FSH e do LH possibilita que, desde a menarca, os ciclos sejam ovulatórios."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-150776","number":"150776","sourceNumber":"150776","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"No ovário, as funções endócrina e reprodutiva estão intimamente ligadas. A produção\nhormonal é dependente da maturação folicular, da qual decorre a ovulação, ao tempo em que a\nimplantação do ovo depende da correta atuação do estradiol e da progesterona sobre o\nendométrio. No caso da produção de esteroides sexuais:","options":{"A":"O desenvolvimento folicular, responsável pela fabricação de estrogênios na primeira fase do\nciclo, ocorre sob ação do LH.","B":"Os precursores androgênicos são produzidos nas células da granulosa, induzidos pelo LH.","C":"O FSH estimula a produção de androgênios a partir das células da teca, tendo como substrato o\ncolesterol.","D":"O FSH induz a aromatização dos androgênios em estrogênios nas células da granulosa."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-157312","number":"157312","sourceNumber":"157312","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre o ciclo menstrual normal, assinale a alternativa CORRETA.","options":{"A":"As células da granulosa convertem colesterol em androstenediona mediante atividade da\naromatase.","B":"O endométrio encontra-se proliferativo durante a fase lútea.","C":"O GnRH é um decapeptídeo secretado de maneira pulsátil do hipotálamo que regula a secreção\nde LH e FSH pela hipófise posterior.","D":"Na fase lútea, a elevação dos níveis de inibina A promove a supressão das gonadotrofinas.","E":"Na primeira fase do ciclo, o folículo dominante é selecionado como consequência da redução do\nFSH."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-111428","number":"111428","sourceNumber":"111428","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à prolactina, é incorreto afirmar:","options":{"A":"É sintetizada em lactotropos.","B":"Sua síntese e secreção são estimuladas por peptídeos hipotalâmicos.","C":"Seu nível aumenta com a gestação.","D":"Sua secreção, no período pós-parto, é estimulada pela sucção.","E":"O estresse diminui sua secreção."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-83690","number":"83690","sourceNumber":"83690","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"SAC, 37 anos, procura o ginecologista para esclarecimentos em relação à\ncontracepção. G2P1 (normal), tabagista (10\ncigarros/dia), negava comorbidades. Em relação aos\ncontraceptivos hormonais temos:","options":{"A":"O tabagismo é uma contraindicação\nabsoluta.","B":"Uso do método geralmente não recomendado, a menos que outros métodos mais\nadequados não estejam disponiveis.","C":"Na classificaçao da OMS seria classe 4.","D":"O número de cigarros/dia nao é fator importante.","E":"O tabagismo é fator de proteção para uso de contraceptivos."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-83862","number":"83862","sourceNumber":"83862","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre o ciclo ovariano:","options":{"A":"apresenta 4 fases: fase folicular, pré-ovulatória, ovulatória e fase lútea.","B":"Na fase lútea ocorre o recrutamento para a seleção do folículo dominante.","C":"A ovulação ocorre em torno de 10 a 12 horas após o pico máximo de LH e 24-36 horas após\ninício da elevação dos níveis de estradiol.","D":"Na fase folicular o FSH permanece em níveis baixos, sendo marcante seu aumento na fase\nlútea.","E":"Os ovários são órgãos que iniciam suas atividades apenas na menarca, já que durante a vida\nintra-uterina e infância encontram-se com ausência de qualquer atividade."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-84421","number":"84421","sourceNumber":"84421","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A respeito da ação dos esteroides sexuais no hipotálamo, é CORRETO afirmar: I. Os\nestrogênios em baixa quantidade inibem a liberação do GnRH; II. Os estrogênios em dose superior\na 200 pg/ml, atuando no hipotálamo por no mínimo 50 horas, exercem retroalimentação positiva; III.\nA progesterona, em qualquer quantidade, inibe a secreção de GnRH por alterar a sua pulsatilidade;\n\nIV. A progesterona exerce retroalimentação positiva sobre a secreção de GnRH; V. Os andrógenos\nexercem ação negativa nos neurônios\nhipotalâmicos. Estão CORRETAS apenas as assertivas:","options":{"A":"I, II, III e IV.","B":"I, II, IV e V.","C":"I, II, III e V.","D":"I, III, IV e V.","E":"Todas."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-85321","number":"85321","sourceNumber":"85321","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A respeito dos mecanismos de retrocontrole responsáveis pela regulação do ciclo\nmestrual, verifica-se que:","options":{"A":"a inibina B produz feedback positivo para FSH durante a segunda metade da fase folicular.","B":"os níveis crescentes de estradiol na fase folicular final produzem feedback positivo para LH.","C":"a produção de estradiol aumenta gradualmente na fase folicular, sendo estimulada por FSH e\ninibina.","D":"o FSH aumenta progressivamente após a ovulação como resposta ao feedback positivo do\nestradiol e progesterona."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-85353","number":"85353","sourceNumber":"85353","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente com 36 anos, está amamentando filho de 5 meses, não de forma exclusiva, é\ntabagista e fuma 20 cigarros por dia. Dentre os métodos a seguir, qual o método contraceptivo mais\nindicado?","options":{"A":"Injetável mensal.","B":"Anticoncepcional hormonal combinado.","C":"Tabelinha.","D":"DIU de cobre."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-61275","number":"61275","sourceNumber":"61275","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação aos hormônios reprodutivos, todas as opções estão corretas, exceto:","options":{"A":"o hormônio de liberação de gonadotrofina (GnRH) e decapeptídio.","B":"a secreção pulsátil contínua de GnRH é necessária porque o GnRH tem meia-vida\nmuito curta.","C":"o GnRH possui funções autócrinas e parácrinas em todo o corpo.","D":"as endorfinas recebem esse nome por sua atividade endógena semelhante à da morfina.","E":"as endorfinas variam durante todo o ciclo menstrual, com níveis mínimos na fase lútea e um\nnível máximo durante a menstruação."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-69212","number":"69212","sourceNumber":"69212","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao ciclo menstrual, é CORRETO afirmar:","options":{"A":"O GnRH é um decapeptídeo que age sobre a neuro-hipófise estimulando a secreção das\ngonadotrofinas.","B":"O LH estimula as células da teca a produzirem androgênios.","C":"A inibina é um hormônio produzido pelo ovário, nas células da teca, e assume função de\nretroalimentação positiva com o FSH.","D":"Na fase lútea o nível de progesterona é baixo e o LH experimenta seu pico de ação.","E":"A enzima aromatase está presente nas células da teca e participam da produção do estradiol."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-61738","number":"61738","sourceNumber":"61738","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a alternativa que traz o nome CORRETO da enzima X: (VER IMAGEM)","options":{"A":"5-alfarredutase.","B":"21-hidroxilase.","C":"Aromatase.","D":"17-beta-hidroxiesteroide-desidrogenase."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-61813","number":"61813","sourceNumber":"61813","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A elaboração de normas internacionais quanto aos critérios médicos de elegibilidade e\nrecomendações de práticas para o uso de anticoncepcionais é um aspecto importante na melhoria\nda qualidade do atendimento em saúde reprodutiva. Com base nesses critérios, entre os métodos\nexpostos abaixo, a melhor opção de anticoncepção para uma mulher nuligesta com migrânea com\naura é:","options":{"A":"Anticoncepcional hormonal combinado injetável.","B":"Anticoncepcional hormonal combinado oral de baixa dose.","C":"Anticoncepcional hormonal combinado via transdêrmico.","D":"Anticoncepcional hormonal combinado por anel vaginal.","E":"Anticoncepcional hormonal de progestágeno."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-48832","number":"48832","sourceNumber":"48832","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Entre as ações abaixo, é própria do estradiol:","options":{"A":"Redução da concentração de SHBG.","B":"Redução dos receptores de FSH.","C":"Aumento da concentração de SHBG.","D":"redução dos fatores VII, X e da anti trombina III.","E":"Aumento dos receptores de Gnrh."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-48988","number":"48988","sourceNumber":"48988","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à ovulação, está correto afirmar: (I) A ovulação ocorre cerca de 10-12 horas\ndo pico de LH. (II) A ovulação ocorre de\n24-36 horas do pico de estradiol. (III) O pico de LH é o\nindicador mais confiável da ovulação. (IV) A retomada da meiose no oócito decorre do pico de\nFSH. (V) Os níveis de estradiol caem muito quando o LH atinge o seu pico. Estão corretas as\nassertivas:","options":{"A":"I, II, III e IV.","B":"I, II, III e V.","C":"I, II, IV e V.","D":"II, III, IV e V.","E":"Todas."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-53629","number":"53629","sourceNumber":"53629","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao ciclo menstrual, é INCORRETO afirmar que:","options":{"A":"o estrogenio tem a capacidade de controlar as gonadotrofinas por um mecanismo de feedback\nnegativo.","B":"o GNRH é secretado em um padrão continuo e é responsável pela liberação pulsátil das\ngonodotrofinas.","C":"o crescimento do foliculo primário até o antral é estimulado principalmente por FSH.","D":"o pico do LH é fundamental para que ocorra ovulação.","E":"todas as alternativas acima estão corretas."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-53561","number":"53561","sourceNumber":"53561","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre a endocrinologia ginecológica, é INCORRETO afirmar que:","options":{"A":"As inibinas são peptídeos produzidos nas gonadas femininas, pelas células da teca.","B":"No ciclo menstrual, o aumento súbito do LH promove a maturação oocitária até o estágio de\nmetafase 2 (dois) e sua liberação do folículo.","C":"Uma forma rara de falência ovariana - hipogonadismohipergonadotrofico - é decorrente da falha\nenzimática da 17-hodroxilase (P450C17) em ambos os ovários e adrenais.","D":"A fase de desenvolvimento folicular FSH-dependente é de aproximadamente 20 dias.","E":"Todas as alternativas acima estão corretas."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-47645","number":"47645","sourceNumber":"47645","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Uma paciente de 19 anos, em uso de contracepção hormonal há três anos, com fluxo\nmenstrual regular de 28:3 dias, esqueceu-se de tomar os dois últimos comprimidos da última\ncartela há vinte dias. Não tem relações sexuais há um mês e ainda não menstruou. A causa mais\nprovável da amenorreia é:","options":{"A":"Gravidez;","B":"Amenorreia pós-pílula.","C":"Hiperplasia endometrial.","D":"Metrose de receptividade."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-47672","number":"47672","sourceNumber":"47672","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A Síndrome de Stein-Leventhal, também conhecida como Doença dos Ovários\nPolicísticos (DOP), é uma condição funcional\nbenigna que acomete mulheres em idade reprodutiva,\nsendo uma importante causa de infertilidade. Essa síndrome:","options":{"A":"É de alta prevalência, acometendo de 30% à 60% das mulheres em idade reprodutiva;","B":"Caracteriza-se pela presença de obesidade, hirsutismo, anovulia crônica, oligomenorreia e\nvirilismo ocasional;","C":"Tem relação direta com hiperplasia ou com o microadenoma hipofisário;","D":"Apresenta ovário com superfície homogênea branco-pardo-acinzentada e raros cistos de\ntamanhos variados na cortical, alguns de conteúdo hemorrágico."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-9297","number":"9297","sourceNumber":"9297","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"É comum haver na tensão pré-menstrual ou na síndrome pré-menstrual:","options":{"A":"diminuição de peso e desidratação.","B":"deficiência de piridoxina associada à insuficiência das vitaminas A e E.","C":"conotação orgânica do sistema neuroendócrino.","D":"piora dos sintomas no início do período menstrual subsequente."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-273989","number":"273989","sourceNumber":"273989","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 61 anos, comparece ao ambulatório de ginecologia referindo perda de\nurina há 1 ano. A mesma refere que não\nconsegue chegar ao banheiro no tempo adequado após o\ninício do desejo miccional. Traz exames já realizados que mostram: estudo urodinâmico com\nhiperatividade do detrusor e pressão de perda ao esforço de 130 cm H?O; Urocultura sem\ncrescimento bacteriano. Diante do exposto, qual a PRINCIPAL hipótese diagnóstica e a MELHOR\nopção de tratamento?","options":{"A":"Incontinência urinária de esforço, por defeito intrínseco/sling transobturatório.","B":"Urgência miccional/sling transobturatório.","C":"Urgência miccional/anti-muscarínicos.","D":"Incontinência urinária de esforço, por hipermobilidade do colo/cirurgia de Burch."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-250242","number":"250242","sourceNumber":"250242","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Esteroides sexuais são produzidos pelas gônadas em um mecanismo conhecido como\n\"dupla célula\" e estimulam os órgãos reprodutores, maturação das células germinativas e as\ncaracterísticas sexuais secundárias. Entre eles, os mais importantes são estradiol, progesterona e\ntestosterona. Quanto ao processo da \"dupla célula\", assinale a alternativa CORRETA:","options":{"A":"O hormônio luteinizante estimula a conversão de androgênios em estrogênios nas células do\nestroma ovariano.","B":"O hormônio folículo estimulante e o hormônio luteinizante agem nas células da teca externa,\nestimulando a transformação de colesterol em esteróides sexuais.","C":"O hormônio folículo estimulante se liga a receptores de membrana na célula da granulosa e\nestimula a atividade da enzima aromatase.","D":"Os androgênios são produzidos, predominantemente, nas células da granulosa e chegam às\ncélulas tecais por difusão simples."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-155324","number":"155324","sourceNumber":"155324","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente do sexo feminino, 56 anos de idade, tem queixas de perda urinária aos\nmédios esforços. Nega outros sintomas como calor,\nirritabilidade ou secura vaginal. Antecedentes\nginecológicos: G3P3 (3 cesarianas). Menopausa há 2 anos, sem uso de Terapia Hormonal (TH).\nSem comorbidades. IMC = 24 kg/m². Sobre esse caso, assinale a alternativa CORRETA:","options":{"A":"Essa paciente deve ser submetida à avaliação urodinâmica, após urinocultura. Se confirmar\nincontinência urinária aos esforços, iniciar tratamento com anticolinérgicos.","B":"Essa paciente deve ser submetida à avaliação urodinâmica, após urinocultura. Se confirmar\nincontinência urinária aos esforços, deverá ser submetida à terapêutica cirúrgica com sling\ntransobturatório.","C":"Deve ser iniciado TH com reavaliação em 3 meses. Sabe-se que a TH melhora o trofismo\nvaginal, corrigindo esse provável diagnóstico de incontinência urinária.","D":"Essa paciente deve ser submetida à avaliação urodinâmica, após urinocultura. Se confirmar\nincontinência urinária aos esforços, deverá ser submetida à terapêutica cirúrgica, com cirurgia de\nKelly Kennedy como primeira opção.","E":"Essa paciente apresenta quadro clínico clássico de urgência miccional, dispensando o estudo\nurodinâmico e deve ser iniciada a terapêutica com anticolinérgicos."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-80922","number":"80922","sourceNumber":"80922","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"O músculo bulbocavernoso insere-se principalmente no cóccix.","B":"O diafragma urogenital contém um compartimento superficial e outro profundo.","C":"O compartimento profundo do diafragma urogenital é sustentado por um grupo de músculos no\ncompartimento superficial, incluindo os músculos perineal transverso superficial, o bulbocavernoso\ne o isquiocavernoso.","D":"O canal anal passa pelo centro do soalho pélvico, que é formado pelos músculos elevador do\nânus e coccígeo.","E":"A artéria ilíaca comum direita prossegue ao longo da borda medial do músculo psoas até a orla\npélvica, onde se divide nas artérias ilíacas externa e hipogástrica."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-62607","number":"62607","sourceNumber":"62607","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a alternativa incorreta relacionada ao ciclo menstrual.","options":{"A":"A progesterona se eleva cerca de 12 horas antes do pico de LH;","B":"A fixação do LH circulante ao receptor específico da membrana dá início ao fenômeno que\nculmina na síntese dos esteroides;","C":"A secreção contida de LH na fase folicular não é secundária ao nível baixo circulatório de\nEstradiol (E2);","D":"Os pulsos de FSH e o LH duram entre 60 e 90 minutos, na fase proliferativa, mas diminuem para\ntrês ou quatro horas na fase lútea;","E":"Toda atividade hipofisária está na dependência de sua conexão vascular com o hipotálamo."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-47419","number":"47419","sourceNumber":"47419","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente com 45 anos, casada, refere que ao sentir vontade de urinar não consegue\nchegar ao banheiro sem que perca urina antes,\nsem antecedentes pessoais ou familiares dignos de\nnota e IIG IIP 0A, partos cesarianos. Qual o provável tratamento para essa paciente?","options":{"A":"Colpoperineoplastia associado a Kelly-Kennedy","B":"Sling vaginal","C":"Fisioterapia perineal","D":"Tratamento clínico","E":"Respostas A e B estão corretas"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-47445","number":"47445","sourceNumber":"47445","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente com 40 anos de idade, com história de troboembolismo e fumante, deseja\nmétodo anticoncepcional. Qual método estaria contraindicado a essa paciente?","options":{"A":"Condom","B":"Dispositivos intrauterinos","C":"Anticoncepcional hormonal oral","D":"Diafragma","E":"Método de Ogino-Knaus."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-35793","number":"35793","sourceNumber":"35793","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a opção CERTA:","options":{"A":"Os quadros anovulatórios podem manifestar-se por irregularidade menstruais ou amenorreia.","B":"A insuficiência lútea é a manifestação mais evidente das disfunções no eixo\ncórtex-hipotálamo-hipófise-ovário.","C":"Insuficiência lútea, anovulação crônica e amenorreia são as manifestações clínicas menos\nfrequentes da irregularidade menstrual.","D":"A terapia de reposição hormonal não deve ser instituída precocemente nos casos de\nirregularidade menstrual.","E":"Os quadros de irregularidade menstrual se estabelecem independentemente dos níveis\nhormonais."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-263701","number":"263701","sourceNumber":"263701","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A Incontinência Urinária (IU) é uma condição que afeta dramaticamente a qualidade de\nvida do paciente, comprometendo o seu bem-estar físico, emocional, psicológico e social.\n\nEstima-se que mais de 8 milhões de brasileiros tenham incontinência urinária. Em relação a IU,\nanalise as afirmativas abaixo e marque a\nalternativa CORRETA: I - É definida como a perda\ninvoluntária de urina. II - É uma patologia que atinge homens e mulheres após os 50 anos de idade.\nIII - É um problema subdiagnosticado e subtratado.","options":{"A":"Apenas as afirmativas I e III estão corretas.","B":"Apenas a afirmativa I está correta.","C":"Apenas as afirmativas II e III estão corretas.","D":"Apenas a afirmativa II está correta.","E":"As afirmativas I, II e III estão corretas."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-263744","number":"263744","sourceNumber":"263744","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Segundo a Sociedade Internacional de Continência, Incontinência Urinária é toda perda\ninvoluntária de urina. A incontinência urinária de esforço (IUE), em sua forma mais comum, é\ndefinida como toda perda de urina decorrente de algum esforço físico como pular, correr e tossir; e\nestá relacionada à hipermobilidade da uretra ou à deficiência do esfincter. Sobre essa condição\nmarque a alternativa INCORRETA:","options":{"A":"A terapêutica da IUE subdivide-se em cirúrgica e clínica, e o tratamento não cirúrgico,\nconservador, vem ganhando realce nos últimos anos\npela melhora dos resultados e dos poucos\nefeitos colaterais que provoca.","B":"O tratamento conservador é considerado como primeira linha terapêutica da IUE, que inclui os\nexercícios perineais, o biofeedback, a eletroestimulação e os cones vaginais.","C":"A terapia hormonal pode ser adjuvante nos tratamentos cirúrgicos e fisioterápicos pela melhora\nda vascularização e do trofismo das estruturas do\nassoalho pélvico.","D":"Durante a anamnese deve-se pesquisar afecções sistêmicas (como doenças neurológicas e\ndiabetes, por exemplo) e o uso de medicações que podem apresentar efeitos colaterais no trato\nurinário. Questionar também a respeito de sintomas relacionados aos prolapsos genitais e à\nincontinência a gases e fezes, visto que é comum sua associação com a incontinência urinária.","E":"O estudo urodinâmico está indicado na avaliação inicial da incontinência urinária."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-278953","number":"278953","sourceNumber":"278953","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Uma mulher de 48 anos, G3P3, tem perda de urina com tosse e espirro. Ela nega\ndisúria ou urgência urinária. Qual das\nalternativas seguintes provavelmente está presente no exame\nfísico?","options":{"A":"Uretra hipermóvel","B":"Retocele","C":"Bexiga hipertrófica","D":"Defeito paravaginal","E":"Prolapso genital total"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-203401","number":"203401","sourceNumber":"203401","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre urgência e incontinência urinária, aponte alternativa CORRETA:","options":{"A":"Na Incontinência Urinária de Esforço (IUE), geralmente seu tratamento é medicamentoso com\nanticolinérgicos.","B":"Na IUE, quando acontece perdas por pequenas pressões, o tratamento geralmente envolve uso\nde sling suburetral.","C":"Urgência miccional geralmente necessita de tratamento cirúrgico, devido falha ser muito grande\ncom abordagem clínica.","D":"A fisioterapia é aliada no tratamento da IUE e nunca utilizada na urgência miccional.","E":"A cirurgia de Burch é tratamento de escolha nos casos refratório de urgência miccional."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-175014","number":"175014","sourceNumber":"175014","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em 1992, Johnson esquematizou a definição de Síndrome de tensão pré-menstrual\n(SPM) usando critérios para definir a tensão\npré-menstrual (TPM). Assinale a opção que NÃO\napresenta um critério de Johnson.","options":{"A":"Presença de mais de um dos sintomas: somáticos (mastalgia, cefaleia, edemas, fadigas, insônia,\ncólicas, etc...); psíquicos (irritabilidade, tensão, depressão, labilidade emocional, ansiedade,\netc...).","B":"Possibilidade de ocorrência de sintomas em qualquer fase lútea inicial.","C":"Ocorrência dos sintomas na fase lútea tardia.","D":"Sintomatologia suficientemente severa para alterar o relacionamento conjugal, profissional e\nsocial.","E":"Presença de mais de um dos sintomas: comportamentais (isolamento social, hiperfagia,\nagressividade, etc ...) congnitivos (confusão\nmental, diminuição da concentração, falta de iniciativa\ne etc...)"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-177549","number":"177549","sourceNumber":"177549","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente 52 anos apresenta queixa de perda de urina, sua queixa é de não conseguir\nchegar ao banheiro no tempo adequado, quando\né iniciado o desejo miccional. Ao realizar\npropedêutica, o estudo urodinâmico que evidenciou hiperatividade do detrusor, pressão de perda\nao esforço de 130 cm H2O e urocultura sem crescimento bacteriano. Qual a principal hipótese\ndiagnóstica e opção de tratamento?","options":{"A":"Incontinência urinária de esforço, devido a defeito intrínseco / sling transobturatório.","B":"Urgência miccional / sling transobturatório.","C":"Incontinência urinária de esforço, devido a hipermobilidade do colo / sling transobturatório.","D":"Urgência miccional / antimuscarínicos.","E":"Incontinência urinária de esforço, devido a hipermobilidade do colo / burch."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-154442","number":"154442","sourceNumber":"154442","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Durante o ciclo menstrual normal, o período menstrual é caracterizado por:","options":{"A":"Queda dos níveis de estrogênio e progesterona, devido à falha da fecundação, sendo\nresponsável pela descamação do endométrio.","B":"Relação direta aos níveis baixos de FSH e LH.","C":"Relação direta a níveis de proteína de apoptose celular endometrial local.","D":"Aumento progressivo de estrogênio e progesterona, após o período ovulatório, que ocorre no\nmeio do ciclo, provocando sangramento quando chega aos seus níveis máximos, descamando o\nendométrio.","E":"Aumento dos níveis de estrogênio e queda da progesterona, provocando um processo\ninflamatório, que faz descamar o endométrio."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-154457","number":"154457","sourceNumber":"154457","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na incontinência urinária de esforço, causada por hipermobilidade do colo vesical, os\nmelhores resultados com tratamento cirúrgico em cinco anos, com taxas de cura que chegam a\n70%, ocorrem com:","options":{"A":"Sling Uretral (Cirurgia de Aldridge).","B":"Colpossuspensão de Burch.","C":"Cirurgia de Kelly Kennedy (Uretroplastia)","D":"Cirurgia de Manchester.","E":"Tension free Vaginal Tape (TVT)."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-140013","number":"140013","sourceNumber":"140013","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Cliente de 31 anos, menarca aos 14 anos, ciclos menstruais regulares com fluxo de 4\ndias, início de atividade sexual aos 18 anos. Teve 5 parceiros. Atualmente com parceiro fixo há\ncerca de 2 anos. Usa condon como método contraceptivo. Recebe exame citopatológico do colo\nuterino com o seguinte resultado: amostra satisfatória, presença de células endocervicais,\nintermediárias, superficiais e metaplasia imatura. A cliente acima expressa desejo de usar outro\nmétodo contraceptivo, mas tem dúvidas sobre qual método utilizar. Assinale a opção que consta\ninformações corretas acerca dos métodos contraceptivos.","options":{"A":"O diu com levonogestrel ( Ing) age liberando hormônio diariamente na cavidade uterina. O Ing\ntem absorção significativa promovendo efeitos sistêmicos consideráveis.","B":"O diu de cobre não afeta a ovulação e age, não apenas na cavidade uterina, mas também fora\ndela, interferindo em várias etapas do processo reprodutivo.","C":"Os anticoncepcionais injetáveis trimestrais são compostos estroprogestogênicos e algumas\nmulheres podem demorar até 1 ano para o restabelecimento do padrão normal da mesntruação,\napós descontinuação do método.","D":"O anticoncepcional em forma de implante tem duração de 3 anos com eficácia muito alta\ndemonstrada pelo elevado índice de pearl, em torno de 3.","E":"Todos os contraceptivos hormonais combinados têm na sua formulação o etinilestradiol."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-103902","number":"103902","sourceNumber":"103902","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A Sociedade Internacional de Continência define incontinência urinária como \"perda\ninvoluntária de urina objetivamente demonstrável que representa um problema social ou higiênico\".\nSobre incontinência urinária, é correto afirmar:","options":{"A":"Quando a perda urinária está exclusivamente relacionada à contração involuntária do músculo\ndetrusor, o tratamento cirúrgico é a primeira escolha.","B":"O tratamento cirúrgico tem como princípio o suporte dos ligamentos cardinais.","C":"A condição de incontinência urinária de urgência consiste na perda urinária constante\nocasionada pela maior pressão da urina retida na bexiga.","D":"As teorias da uretra curta e perda do ângulo uretrovesical são as que melhor explicam as causas\nda incontinência urinária de esforço.","E":"Na mulher, as alterações esfincterianas mais comuns que causam incontinência urinária estão\nrelacionadas à hipermobilidade da uretra e à deficiência uretral intrínseca."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-107919","number":"107919","sourceNumber":"107919","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na distopia genital, pode-se dizer que a manutenção da estática dos órgãos pélvicos é\nfeita por dois aparelhos anatômicos: o aparelho de suspensão e o de sustentação. Faz parte do\naparelho de sustentação, EXCETO:","options":{"A":"Diafragma pélvico (músculo elevador do ânus e músculo isquiococcígeo).","B":"Músculos esfícter-anal, isquiocavernosos, bulbocavernosos e transversos superficiais do\nperíneo.","C":"Ligamento redondo.","D":"Diafragma urogenital (músculo transverso profundo do períneo).","E":"Fáscia endopélvica."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-87493","number":"87493","sourceNumber":"87493","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre as distopias genitais, é correto afirmar:","options":{"A":"A cistouretrocele pode ocorrer em pacientes nulíparas.","B":"A cistocele é responsável pela incontinência urinária de esforço.","C":"Os ligamentos redondos são os que evitam o prolapso uterino.","D":"A retocele é ocasionada pela ruptura da fáscia pubovesicocervical.","E":"A retocele é causada pela diástase dos músculos piramidais."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-87495","number":"87495","sourceNumber":"87495","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O prolapso genital é queixa comum na pós-menopausa. A cirurgia muitas vezes é\nnecessária para correção da distopia. O reparo paravaginal é usado para correção da(o):","options":{"A":"Cistocele;","B":"Retocele;","C":"Prolapso da cúpula vaginal;","D":"Laceração perineal de 3° grau;","E":"Prolapso retovesical."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-87506","number":"87506","sourceNumber":"87506","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O diafragma pélvico é formado pelos músculos:","options":{"A":"Músculo elevador do ânus e músculo isquiococcígeo;","B":"Músculo transverso profundo do períneo e pelo esfíncter uretral externo;","C":"Músculos isquiocavernosos, bulbocavernoso e transverso superficial do períneo;","D":"Músculos elevador do ânus e músculo isquiocavernoso;","E":"Músculo transverso profundo do períneo, piramidais e pelo esfíncter uretral externo."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-89221","number":"89221","sourceNumber":"89221","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Qual das estruturas é considerada de importância primária na sustentação do útero e\ncujo relaxamento é a causa principal de prolapso uterino?","options":{"A":"Ligamento transverso de Mackenrodt","B":"Ligamento redondo","C":"Ligamento uterossacro","D":"Ligamento infundibulopélvico","E":"Nenhuma das estruturas acimas"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-89230","number":"89230","sourceNumber":"89230","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"São contraindicações absolutas para uso de TH (Terapia de Reposição Hormonal),\nexceto:","options":{"A":"Tromboembolismo agudo.","B":"Doença hepática severa em atividade.","C":"Diabetes mellitus.","D":"Carcinoma de endométrio e de mama recém-tratados e recorrentes.","E":"Sangramento vaginal de origem não diagnosticada."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-52148","number":"52148","sourceNumber":"52148","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"São tratamentos do prolapso uterino, EXCETO:","options":{"A":"Colpocleise","B":"Histerectomia vaginal com aproximação das estruturas ligamentares","C":"Uso de telas sintéticas","D":"Fisioterapia uroginecológica","E":"Cirurgia de Burch"},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-327346","number":"327346","sourceNumber":"327346","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher, 23 anos, sem uso de contraceptivos há 3 meses, apresenta ciclos menstruais\nregulares com 28 dias de intervalo. Para detectar seu período fértil, ela vem observando as\nmodificações fisiológicas de sua secreção vaginal. Há 1 semana notou a presença de muco\nabundante e filante, mas hoje a secreção está mais escassa e viscosa. Qual o perfil das\ngonadotrofinas encontrado hoje?","options":{"A":"Ascensão constante desde o início do ciclo","B":"Queda em relação ao início do ciclo","C":"Secreção estável desde o início do ciclo","D":"Queda em relação ao meio do ciclo"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-346662","number":"346662","sourceNumber":"346662","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A incontinência urinária de esforço (IUE) é o tipo de perda de urina mais comum em\nmulheres e podemos indicar tratamento não cirúrgico ou cirúrgico. Em relação a esse assunto,\nassinale a alternativa ERRADA:","options":{"A":"As intervenções no estilo de vida reduzem a ocorrência de IUE","B":"O tratamento cirúrgico pode ser realizado com os slings por via retropúbica e transbturatória","C":"Os exercícios da musculatura do assoalho pélvico não devem ser indicados como primeira linha\nde tratamento","D":"Os pessários com suporte podem ser indicados como tratamento conservador"},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-316016","number":"316016","sourceNumber":"316016","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Quando a musculatura pélvica é lesada, os órgãos pélvicos se mantêm em posição\nsomente pela ação de:","options":{"A":"Arquitetura própria de cada órgão e suas relações","B":"Plexos vasculares e nervosos","C":"Dobras peritoneais","D":"Bacia óssea","E":"Ligamentos e fáscias"},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-267322","number":"267322","sourceNumber":"267322","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ciclo menstrual é o principal responsável por modificações da fisiologia feminina, o\nqual pode afetar algumas respostas morfofuncionais. Em relação à fisiologia do ciclo menstrual,\nassinale a afirmativa correta.","options":{"A":"O hormônio foliculoestimulante (FSH) e o hormônio luteinizante (LH) são produzidos pela\nadeno-hipófise.","B":"O hormônio foliculoestimulante (FSH) é responsável pela menstruação.","C":"O endométrio proliferativo contém pequeno número de glândulas, células estromais e células\nvasculares endoteliais.","D":"O corpo lúteo é formado durante a menstruação."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-244800","number":"244800","sourceNumber":"244800","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a alternativa que preenche corretamente as lacunas do parágrafo a seguir: O\n\n(A) é a técnica mais utilizada na correção dos prolapsos da parede vaginal\nanterior e consiste na correção dos defeitos do(a)","options":{"A":"sling autólogo; fáscia endopélvica","B":"reparo paravaginal; elevador do ânus","C":"sacrocolpopexia; fáscia retovaginal","D":"colpoplastia anterior; fáscia pubocervical","E":"colpossuspensão; arco tendíneo da fáscia pélvica"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-255342","number":"255342","sourceNumber":"255342","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Não é causa de prolapso genital:","options":{"A":"bacia ginecóide.","B":"doença pulmonar obstrutiva crônica.","C":"partos vaginais.","D":"obstipação crônica."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-244807","number":"244807","sourceNumber":"244807","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Uma mulher de 37 anos, com 2 partos vaginais, queixa-se de perda de urina aos\ngrandes esforços quando com bexiga cheia. Nega\noutros sintomas, mas apresenta prolapso de\nparede vaginal anterior de pequena monta, com boa função neuromuscular do assoalho pélvico.\nAlém disso, apresenta urina residual desprezível. A conduta mais adequada é:","options":{"A":"Administração de medicação anticolinérgica","B":"Fisioterapia do assoalho pélvico","C":"Cirurgia de Burch","D":"Cirurgia de sling","E":"Colpossuspensão retropúbica"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-221034","number":"221034","sourceNumber":"221034","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação ao ciclo menstrual, marque V para as afirmativas verdadeiras e F para as\nfalsas. ( ) Nas células da granulosa, os androgênios produzidos na teca são convertidos em\nestrogênios pela ação da enzima aromatase, mecanismo das duas células. ( ) Os estrogênios têm a\nprioridade de reduzir os receptores de FSH na granulosa. ( ) Na metade da fase folicular sob a\ninfluência do estrogênio, os níveis de LH se elevam juntamente com seus receptores nas células da\nteca. ( ) O LH estimulará a produção de estrogênio nas células da teca que inibirá a liberação de\nFSH pela hipófise. Assinale a sequência correta.","options":{"A":"V, V, F, F","B":"V, F, V, F","C":"F, F, V, V","D":"F, V, F ,V"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-208604","number":"208604","sourceNumber":"208604","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O tratamento farmacológico da incontinência urinária de esforço pode ser, inicialmente,\nrealizado com diversos medicamentos. Dentre\nos relacionados a seguir, qual apresenta a melhor\neficácia?","options":{"A":"efedrina","B":"propranolol","C":"clembuterol","D":"imipramimna","E":"duloxetina"},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-214535","number":"214535","sourceNumber":"214535","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na fisiologia do ciclo menstrual, o pico do LH se mantém por:","options":{"A":"24 a 36 horas.","B":"10 a 12 horas.","C":"24 a 48 horas.","D":"48 a 50 horas."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-208517","number":"208517","sourceNumber":"208517","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A indicação mais comum para pessário vaginal é:","options":{"A":"prolapso de órgão pélvico","B":"divertículo uretral","C":"incontinência anal","D":"fístula retovaginal","E":"distúrbio anorretral funcional"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-177323","number":"177323","sourceNumber":"177323","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Uma mulher de 62 anos refere perda urinária aos esforços, urgência miccional e\nnoctúria, mas nega terapia hormonal. O\nestudo urudinâmico revela pressão de perda sob esforço\nde 55cmH2O, volume residual de 5mL, capacidade e complacência vesical normal, e a\nurufluxometria tem padrão não obstrutivo e contrações não inibidas do detrusor de alta amplitude.\nO diagnóstico e a conduta são:","options":{"A":"incontinência mista; tratamento deve ser feito com sling e a reavaliação posteriormente","B":"incontinência urinária de esforço, tratamento deve ser feito com sling","C":"hiperatividade do detrusorm prescrição de anticolinérgicos","D":"incontinência mista, prescrição de anticolinérgicos","E":"nenhumas das alternativas anteriores"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-177333","number":"177333","sourceNumber":"177333","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Analise as asserções a seguir e a relação proposta entre elas: I - A oxibutinina é\nconsiderada a 1ª escolha no tratamento farmacológico da incontinência urinária de urgência\nporque; II - A oxibutinina é o anticolinérgico que apresenta melhor relação custo-efetividade entre\nas drogas anticolinérgicas. A respeito dessas asserções, assinale a opção correta:","options":{"A":"as asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I","B":"as asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I","C":"a asserção I é uma proporção verdadeira, e a II é uma proposição falsa","D":"a asserção I é uma proporção falsa, e a II é uma proposição verdadeira","E":"as asserções I e II são proposições falsas"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-167795","number":"167795","sourceNumber":"167795","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Para a realização do diagnóstico da incontinência urinária de esforço, é importante a\navaliação clínica. Na história patológica pregressa, realizar o inventário detalhado das medicações\nutilizadas pela paciente. A coluna da esquerda apresenta substância utilizada pela paciente e a da\ndireita, os mecanismos dos efeitos esperados no sistema urinário. Numere a coluna da direita de\nacordo com a da esquerda. 1 - Bloqueadores alfa adrenérgicos; 2 - Inibidores da ECA; 3 -\nBloqueadores do canal de cálcio; 4 - Inibidores da COX-2; 5 - Diuréticos. ( ) Relaxamento do\nesfíncter uretral interno e perda involuntária de urina. ( ) Retenção hídrica e diurese noturna. ( )\nAumento da frequência urinária, urgência e poliúria. ( ) Tosse crônica e vazamento urinário. ( )\nRelaxamento da bexiga, retenção hídrica, retenção urinária e diurese noturna. Assinale a sequência\ncorreta.","options":{"A":"1, 4, 5, 2, 3.","B":"3, 2, 4, 5, 1.","C":"1, 5, 4, 3, 2.","D":"5, 4, 3, 2, 1."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-156512","number":"156512","sourceNumber":"156512","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à incontinência urinária de esforço, marque a opção INCORRETA:","options":{"A":"É a forma mais comum de perda involuntária de urina nas mulheres.","B":"Maior risco em multíparas.","C":"No defeito esfincteriano intrínseco a pressão de perda uretral é < 60 cm H2O.","D":"Bloqueador alfa-adrenégico é opção de tratamento."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-156514","number":"156514","sourceNumber":"156514","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre as distopias genitais e os seus respectivos tratamentos, marque a alternativa\ncom a correlação CORRETA: 1. Cistocele; 2.\nRetocele; 3. Prolapso uterino Estagio IV; 4.\n\nAlongamento hipertrófico do colo; ( ) Colporrafia posterior; ( ) Cirurgia de Manchester; ( )\nHisterectomia; ( ) Colporrafia anterior:","options":{"A":"2, 4, 3, 1.","B":"2, 3, 4, 1.","C":"3, 4, 1, 2.","D":"3, 1, 4, 2."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-156413","number":"156413","sourceNumber":"156413","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Para que ocorra ovulação no ciclo menstrual, ela deve ser precedida por picos\nhormonais de:","options":{"A":"Estradiol e FSH.","B":"Progesterona e FSH.","C":"Estradiol e LH.","D":"Progesterona e LH."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-136719","number":"136719","sourceNumber":"136719","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação a síndrome pré-menstrual marque as afirmativas com \"V\" para verdadeiro\nou \"F\" para falso e depois assinale a\nsequência CORRETA. ( ) Os sinais e sintomas são físicos e\npsicológicos ou comportamentais, apresentando relação temporal com o período pré-menstrual e\ncom características de repetição a cada novo ciclo; ( ) Estão entre os sinais e sintomas frequentes:\naumento do tamanho e da sensibilidade das mamas; ganho de peso; irritabilidade; depressão;\nmudanças de humor e do paladar; ( ) É importante diferenciar a síndrome pré-menstrual de outras\ndoenças com sintomas similares, como depressão, ansiedade e psicoses; ( ) É indicado a dosagem\nde hormônios esteroides ovarianos para o diagnóstico etiológico de síndrome pré-menstrual devido\na associação a anormalidades na produção desses hormônios.","options":{"A":"V, V, V, F.","B":"V, F, V, F.","C":"F, V, F, V.","D":"V, F, F, V."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-136965","number":"136965","sourceNumber":"136965","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Considerando-se as variações hormonais ao longo do ciclo menstrual, assinale a\nafirmativa CORRETA.","options":{"A":"A queda da inibina produzida pelo corpo lúteo estimula a secreção de FSH que iniciará um novo\nciclo menstrual.","B":"LH e FSH estão elevados no início da fase folicular.","C":"Os níveis de estrogênio diminuem no inicio da fase lútea, imediatamente antes da ovulação, e\naumentam a partir do meio da fase lútea, como resultado da secreção do corpo lúteo.","D":"Progesterona e estrogênio estimulam a secreção de gonadotrofinas no final da fase lútea e um\nnovo folículo inicia crescimento."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-108075","number":"108075","sourceNumber":"108075","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 30 anos apresentando todos os meses antes da menstruação quadro grave\nde alteração de humor, instabilidade afetiva,\nirritabilidade e cefaléia, com prejuízo na relação com o\ncônjuge e no desempenho no trabalho, tem como principal hipótese diagnóstica:","options":{"A":"Síndrome pré-menstrual.","B":"Transtorno bipolar.","C":"Dismenorréia.","D":"Transtorno disfórico pré-menstrual."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-108092","number":"108092","sourceNumber":"108092","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na incontinência urinária por esforço, podem fazer parte do tratamento, exceto:","options":{"A":"Fisioterapia.","B":"Antidepressivos Tricíclicos.","C":"Alfa-Adrenérgicos.","D":"Eletroestimulação."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-85010","number":"85010","sourceNumber":"85010","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação aos eventos puberais, analise as afirmativas abaixo. I - A menarca só\nocorre após o desenvolvimento completo das\nmamas. II - O pico máximo da velocidade de\ncrescimento estatural ocorre um ano antes da menarca. III - Vários hormônios influenciam o estirão\nde crescimento. IV - No início da puberdade, a liberação do LH ocorre de maneira pulsátil e\nprincipalmente durante o período noturno. Está correto o que se afirma em:","options":{"A":"I, II e III, apenas.","B":"II e IV, apenas.","C":"I, II, III e IV.","D":"III e IV, apenas."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-85020","number":"85020","sourceNumber":"85020","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 25 anos refere amenorreia secundária há 9 meses. O exame ginecológico\nevidencia muco cervical filante e abundante. Sobre os exames a serem solicitados para a\ninvestigação diagnóstica, considere: I - Progesterona; II - Prolactina; III - Estradiol IV - TSH.\nSão\nexames necessários:","options":{"A":"II e IV, apenas","B":"I e III, apenas.","C":"III e IV, apenas.","D":"I, II, III e IV."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-75407","number":"75407","sourceNumber":"75407","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 25 anos procurou o médico queixando-se de que no período pré-menstrual\napresenta depressão, crises de choro, distensão\nabdominal e mastalgia. Diante desse quadro, o\nmédico explicou-lhe que poderia lhe prescrever alguns medicamentos eficazes, nos quais NÃO se\ninclui:","options":{"A":"ácido mefenâmico.","B":"espironolactona.","C":"ácido nalidíxico.","D":"cálcio."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-75420","number":"75420","sourceNumber":"75420","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Os níveis de progesterona da fase lútea são responsáveis por:","options":{"A":"modificações proliferativas endometriais.","B":"redução da pulsatilidade do LH.","C":"filância do muco cervical.","D":"extrusão do óvulo pelo ovário."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-309756","number":"309756","sourceNumber":"309756","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com base nos conhecimentos de anatomia dos órgãos genitais femininos, o prolapso\nuterino está relacionado principalmente com lesão dos ligamentos:","options":{"A":"Largos.","B":"Cardinais.","C":"Redondos.","D":"Pubovesicais.","E":"Infundibulares."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-301627","number":"301627","sourceNumber":"301627","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 28 anos com ciclos ovulatórios de 26 dias, quer saber em qual dia do ciclo\nocorre a ovulação. O ginecologista deve responder que, neste caso, a ovulação provavelmente\ndeve ocorrer no:","options":{"A":"10º dia.","B":"12º dia.","C":"14º dia.","D":"16º dia."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-274915","number":"274915","sourceNumber":"274915","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente do sexo feminino, 59 anos, G2P2N, queixa-se de urgência urinária há 1 ano e\nperda de urina quando espirra. Apresenta atrofia genital e o estudo urodinâmico evidenciou perda\nde urina à manobra de Valsalva, com pressão vesical de 110 cm H2O. Para esse caso, o\ndiagnóstico correto é","options":{"A":"incontinência urinária mista.","B":"deficiência esfincteriana intrínseca.","C":"urge-incontinência.","D":"fístula vesicovaginal.","E":"incontinência urinária de esforço."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-243744","number":"243744","sourceNumber":"243744","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A incontinência urinária é muito prevalente em idosos e está associada à\nestigmatização e isolamento social, além de\npredispor a infecções. A respeito da incontinência\nurinária, é correto afirmar:","options":{"A":"a incontinência urinária por estresse é a causa mais comum de incontinência em pacientes\nidosos","B":"terapias comportamentais não são efetivas no manejo específico da incontinência urinária de\nurgência","C":"o estudo urodinâmico completo deve ser realizado em todo paciente com queixa de\nincontinência urinária","D":"a deficiência de estrogênio causa atrofia da mucosa vaginal, à qual se associa a incontinência\nurinária na mulher após a menopausa"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-239664","number":"239664","sourceNumber":"239664","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Não é ramo da artéria ilíaca interna:","options":{"A":"artéria ovariana","B":"artéria uterina","C":"artéria vesical superior","D":"artéria retal média"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-216834","number":"216834","sourceNumber":"216834","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Pacientes que apresentam prolapso útero vesical podemos afirmar que:","options":{"A":"Pacientes com prolapso útero-genital completo, após a cirurgia de correção, podem apresentar\nincontinência urinária não associada ao esforço.","B":"Paciente com prolapso genital completo, devem realizar estudo urodinâmico pré-operatório,\nsomente se houver repercussão clínica\ndecorrente de acotovelamento uretral.","C":"O uso de estrogenoterapia tópica está indicado apenas para as pacientes que além da\nnecessidade de cirurgia, são sexualmente ativas.","D":"A fixação da cúpula vaginal, após a retirada do útero, pode ser realizada utilizando-se o\nancoramento nos ligamentos largos."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-216881","number":"216881","sourceNumber":"216881","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao uso de telas sintéticas na correção cirúrgica de incontinência urinária,\npodemos afirmar que:","options":{"A":"O uso de telas sintéticas para correção cirúrgica de incontinência urinária de esforço, dispensam\na preparação da mucosa vaginal, através do uso de\nterapia estrogênica tópica.","B":"O uso de telas sintéticas para correção cirúrgica de incontinência urinária de esforço, fez com\nque a cirurgia de Burch passasse a ser\ncontraindicada.","C":"Após a realização de correção cirúrgica de incontinência urinária de esforço com uso de tela\nsuburetral, as taxas de cura em 10 anos, são iguais às da cirurgia de Burch.","D":"A correção de incontinência urinária por hiperatividade detrusora com tela com fixação\nsuprapúbica, tem taxas de cura melhores do que, quando se utiliza tela com fixação\ntransobturatória."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-187391","number":"187391","sourceNumber":"187391","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 36 anos, tem um filho de dois anos e quer usar método anticoncepcional\nainda por mais um ano, para então engravidar\nnovamente. Ela é tabagista (10 cigarros por dia) e\nhipertensa com PA=160x100 mmHg, fazendo uso de captopril e hidroclorotiazida. Qual a orientação\ncontraceptiva para esta paciente:","options":{"A":"Laqueadura tubária pelo risco gestacional","B":"Acetato de medroxiprogesterona trimestral","C":"Anticoncepcional hormonal combinado oral","D":"Anticoncepcional hormonal oral de progestagênio","E":"Anticoncepcional hormonal combinado injetável"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-183375","number":"183375","sourceNumber":"183375","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente, 45 anos de idade, G2P2c, submetida à histerectomia total abdominal há 15\ndias, devido à miomatose uterina, apresenta\nqueixa de perda urinária contínua, relatando umidade\nconstante na vagina. Ao exame, constata-se: Pressão arterial 120/70, frequência cardíaca 88 bpm,\nafebril e eupneica, abdome flácido, doloroso à palpação profunda em hipogástrio sem sinais de\nirritação peritoneal. O exame especular evidencia moderada quantidade de urina em fundo de saco.\nPara esse caso, qual o diagnóstico mais provável?","options":{"A":"Incotinência urinária de esforço.","B":"Bexiga neurogênica.","C":"Fístula vesicovaginal.","D":"Incontinência urinária mista.","E":"Infecção urinária."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-183406","number":"183406","sourceNumber":"183406","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 53 anos de idade, obesa e portadora de diabetes melito, queixa-se de\nperda urinária, quatro a cinco vezes por dia,\ngeralmente após tossir, espirrar ou levantamento de\npeso. Refere também alguns episódios de urgência miccional. Ao exame físico, foram identificadas\nperda urinária à manobra de Valsalva e ausência de distopia genital. Pressão arterial = 130 x 90;\nFC = 92 bpm; glicemia capilar = 188. Possui urinocultura negativa realizada há 1 mês. Nesse caso,\nqual o diagnóstico mais provável e qual exame mais indicado para elucidação diagnóstica?","options":{"A":"Incontinência urinária mista e estudo urodinâmico.","B":"Infecção urinária e urinocultura.","C":"Incontinência urinária mista e urinocultura.","D":"Infecção urinária e cistoscopia.","E":"Incontinência urinária de esforço genuína e estudo urodinâmico."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-177898","number":"177898","sourceNumber":"177898","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com referência ao prolapso genital, segundo a teoria POP-Q (Pelvic Organ Prolapse\nQuantification System), uma mulher histerectomizada possui todos os pontos e medidas de uma\nmulher com útero, EXCETO:","options":{"A":"Ponto Aa (A anterior).","B":"Ponto Ba (B anterior).","C":"Ponto C.","D":"Ponto D.","E":"CVT (Comprimento Vaginal Total)."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-151647","number":"151647","sourceNumber":"151647","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Sobre a Tensão Pré-Menstrual (TPM) e o Transtorno Disfórico Pré-Menstrual (TDPM)\npodemos afirmar: I. As pacientes com tensão\npré-menstrual têm seus sintomas exacerbados em\nrelação a TDPM uma semana antes da menstruação ( ). II. Em geral, mudanças no estilo de vida,\nalimentar-se com uma dieta rica em fibras e exercícios físicos melhoram os sintomas ( ). III.\nApresentam melhora com a utilização de métodos anticonceptivos que suprimem o ciclo menstrual\ne impedem as oscilações hormonais ( ). IV. A piora dos sintomas ocorre na fase folicular devido ao\naumento da progesterona e do hormônio folículo estimulante ( ). Assinale Falso (F) ou Verdadeiro\n(V):","options":{"A":"F, V, V, F.","B":"V, F, F, V.","C":"V, F, V, F.","D":"V, V, V, F."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-151034","number":"151034","sourceNumber":"151034","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"As células endócrinas sintetizam e secretam moléculas sinalizadoras denominadas\nhormônios. A respeito dos hormônios, é INCORRETO afirmar que:","options":{"A":"Circulam normalmente em baixíssimas concentrações, da ordem de pico a micromolar.","B":"Desencadeiam uma série de respostas celulares que são amplificadas e se propagam em\ncascatas.","C":"Podem ser proteicos, esteroides ou aminados derivados de aminoácidos.","D":"Os hormônios esteroides são hidrossolúveis e sintetizados no organismo a partir do colesterol."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-152226","number":"152226","sourceNumber":"152226","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Qual é a MELHOR época do ciclo para se realizar a dosagem de progesterona\nplasmática e avaliar se houve ovulação?","options":{"A":"Do 2º ao 6º dia do ciclo.","B":"Do 7º ao 12º dia do ciclo.","C":"Do 13º ao 14º dia do ciclo.","D":"Do 21º ao 24º dia do ciclo."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-152233","number":"152233","sourceNumber":"152233","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Querendo evitar gravidez, sem levantar suspeitas dos pais, uma adolescente avaliava\nseu período fértil baseada no chamado método\nde Billings (ou muco cervical) cuja característica\nbaseia-se na fluidez e elasticidade do muco cervical, comparáveis à clara de ovo cru. Essas\ncaracterísticas se devem à ação de qual hormônio?","options":{"A":"FSH.","B":"Estrogênio.","C":"LH.","D":"Prostaglandinas."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-155650","number":"155650","sourceNumber":"155650","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente M.G.D.C., 76 anos, G3PC2A1, diabética, hipertensa e DPOC, com vida sexual\nativa, vem apresentando perda de urina em pequena quantidade há 1 mês, relata ainda que essa\nperda urinária piora após seus exercícios diários na academia e ao tossir. No consultório, essa\npaciente receberia o diagnóstico de:","options":{"A":"Urgeincontinência.","B":"Incontinência Urinária por transbordamento.","C":"Incontinência Urinária funcional.","D":"Incontinência Urinária de esforço.","E":"Incontinência Urinária mista."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-152257","number":"152257","sourceNumber":"152257","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Durante o ciclo menstrual regular (ovulatório), na fase Folicular, aponte a alternativa\ncontendo as características hormonais.","options":{"A":"Pulsos de GnRH raros, progesterona baixa e estrogênio crescente.","B":"Pulsos de GnRH frequentes, progesterona alta e estrogênio decrescente.","C":"Pulsos de GnRH raros, progesterona alta e estrogênio decrescente.","D":"Pulsos de GnRH frequentes, progesterona baixa e estrogênio crescente."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-155658","number":"155658","sourceNumber":"155658","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A dor associada à ruptura folículo ovariano no momento da ovulação é denominada:","options":{"A":"Mittelschmerz.","B":"Síndrome de Fitz-Hugh-Curtis.","C":"Síndrome de McBurney.","D":"Síndrome do ovário remanescente.","E":"Síndrome da bexiga dolorosa."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-152265","number":"152265","sourceNumber":"152265","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Importante mecanismo de regulação do ciclo ovulatório são as interações\nendocrinológicas entre os diversos órgãos femininos.\nNesse caso, assinale a alternativa que\napresenta o MELHOR exemplo de feedback de alça longa.","options":{"A":"Hipotálamo-hipófise.","B":"Tireoide-ovário.","C":"Ovário-hipófise.","D":"Endométrio-hipófise."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-140353","number":"140353","sourceNumber":"140353","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O diafragma urogenital é formado pelos músculos","options":{"A":"Transverso superficial do períneo e esfíncter uretral externo.","B":"Elevador do ânus e coccígeos.","C":"Glúteo máximo e isquio coccígeos.","D":"Transverso profundo do períneo e esfíncter uretral externo.","E":"Todos acima."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-130026","number":"130026","sourceNumber":"130026","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O diagnóstico a ser investigado inicialmente no caso de incontinência urinária de\nurgência é:","options":{"A":"Infecção urinária","B":"Bexiga hiperativa","C":"Instabilidade do detrusor","D":"Cistocele"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-111733","number":"111733","sourceNumber":"111733","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A cirurgia para correção de incontinência urinária de esforço considerada de baixa\ncomplexidade, minimamente invasiva, com altas taxas de cura após 10 anos e rápido tempo de\nexecução é:","options":{"A":"Kelly Kennedy.","B":"Cistopexia a Marshall-Marchetti.","C":"Cirurgia de Stamey.","D":"Cirurgia de Burch.","E":"Sling suburetral."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-106757","number":"106757","sourceNumber":"106757","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"NÃO é efeito do estrogênio:","options":{"A":"Predominância de células superficiais no epitélio vaginal.","B":"Elevação superior a 0,5°C na temperatura corporal basal.","C":"Sangramento vaginal após administração de progesterona.","D":"Proliferação endometrial.","E":"Efeito samambaia no muco cervical ressecado."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-106782","number":"106782","sourceNumber":"106782","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A cirurgia de Schauta pode ser realizada no tratamento de:","options":{"A":"Tumor benigno da mama.","B":"Endometriose ovariana.","C":"Câncer de endométrio em mulheres com prolapso genital.","D":"Incontinência urinária de esforço.","E":"Útero bicorno e/ou septado."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-106776","number":"106776","sourceNumber":"106776","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação ao ciclo menstrual e ovulação, assinale a alternativa CORRETA:","options":{"A":"A iniciação do crescimento folicular é dependente do estímulo das gonadotrofinas hipofisárias, e\ninicia-se logo após o início do fluxo menstrual.","B":"A seleção do folículo dominante depende basicamente do microambiente folicular e expressa\ntanto a interação local entre FSH e\nestrogênio, como o efeito estrogênico na secreção hipofisária de\nFSH.","C":"O desenvolvimento dos receptores de LH depende da ação do GnRH e do estriol sobre as\ncélulas da teca.","D":"O padrão de secreção de gonadotrofinas observado no ciclo menstrual é estritamente\ndependente do GnRH e correlaciona-se pouco com a produção de estrogênios.","E":"No período pré-ovulatório, a concentração plasmática de 17-alfa-hidroxiprogesterona está\nelevada, pois este esteroide apresenta significativa importância na regulação cíclica do ciclo\nmenstrual."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-106971","number":"106971","sourceNumber":"106971","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 45 anos, G4P4A0C1, refere perda de urina aos mínimos esforços há 6\nmeses quando tosse e espirra, nega urgência\nmiccional, nega urge incontinência, nega nictúria e\nnega disúria e polaciúria. Ao exame ginecológico observa-se cistocele grau II e perda de urina à\nvalsalva. O diagnóstico para esse caso é:","options":{"A":"Hiperatividade do músculo detrusor.","B":"Hipermobilidade vesical.","C":"Bexiga neurogênica.","D":"Infecção urinária."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-81138","number":"81138","sourceNumber":"81138","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Nas pacientes que referem perda de urina aos pequenos esforços, provavelmente, sua\nincontinência urinária de esforço se deve a:","options":{"A":"Bexiga Neurogênica.","B":"Infecção urinária de repetição.","C":"Contrações vesicais não inibidas.","D":"Fístula uretrovaginal.","E":"Deficiência esfincteriana."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-60170","number":"60170","sourceNumber":"60170","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao ciclo menstrual, para que ocorra um funcionamento adequado do eixo\nhipotálamo-hipófise-ovário e, consequentemente, se mantenha a homeostase endócrina feminina, é\nfundamental a sincronia de várias etapas. Com relação à ovulação, aproximadamente 24h e 12h\nantes da postura ovular, há pico dos seguintes hormônios, respectivamente:","options":{"A":"LH e FSH.","B":"LH e estradiol.","C":"FSH e progesterona.","D":"Estradiol e LH.","E":"Estradiol e progesterona."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-45511","number":"45511","sourceNumber":"45511","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O músculo que compõe o diafragma urogenital é o:","options":{"A":"Transverso superficial.","B":"Bulbocavernoso.","C":"Isquiocavernoso.","D":"Transverso profundo.","E":"Levantador do ânus."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-45513","number":"45513","sourceNumber":"45513","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em caso de prolapso uterino total em paciente idosa, com alto risco cirúrgico e sem\natividade sexual, deve-se optar pelo procedimento cirúrgico de colpocleise, que consiste\ntecnicamente em:","options":{"A":"Colpoplastia anterior.","B":"Colpectomia.","C":"Colpoplastia posterior.","D":"Histerectomia vaginal.","E":"Amputação do colo e colpoplastia anterior e posterior."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-34528","number":"34528","sourceNumber":"34528","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Assinale a afirmação CORRETA sobre os níveis hormonais no ciclo menstrual:","options":{"A":"Elevação de estradiol na fase pré-ovulatória.","B":"Decréscimo gradativo de prolactina do início ao fim do ciclo.","C":"Elevação do nível de LH no momento da ovulação.","D":"Nível máximo de progesterona 48 horas antes da ovulação.","E":"Nível mais elevado de FSH nos 3 primeiros dias do ciclo."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-25715","number":"25715","sourceNumber":"25715","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente com 32 anos, durante o exame clínico, apresentou perda urinária em posição\nortostática, em grande quantidade, sob forma de jato contínuo, alguns segundos após o esforço\nsolicitado (tosse). O quadro indica:","options":{"A":"Lesão neurológica adquirida","B":"Instabilidade do músculo detrusor","C":"Lesão anatômica do assoalho pélvico","D":"Lesão esfincteriana intrínseca da uretra","E":"Cistite Intersticial"},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-8774","number":"8774","sourceNumber":"8774","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação aos esteroides sexuais estão corretas as afirmações abaixo, exceto:","options":{"A":"a conversão periférica pela supra-renal em estrona está aumentada em mulheres obesas.","B":"os estrógenos circulantes constituem a soma da secreção ovariana direta de estradiol e estrona,\nmais a conversão periférica de precursores\nC-19.","C":"o estriol é o metabólico periférico da estrona e estradiol, não sendo produzido diretamente pelo\novário.","D":"os esteroides sexuais ligam-se a receptores localizados na membrana celular das células alvo.","E":"a progesterona é convertida em estriol pelas células hepáticas."},"answer":"E","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-8786","number":"8786","sourceNumber":"8786","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na incontinência urinária de esforço, a ultrassonografia avalia:","options":{"A":"O grau de inclinação da uretra.","B":"A forma do colo vesical.","C":"A amplitude de deslocamento do colo vesical.","D":"O desvio rotacional do colo vesical.","E":"O ângulo entre o colo vesical e os músculos elevadores do ânus."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-359441","number":"359441","sourceNumber":"359441","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"É esperado que ocorra durante um ciclo menstrual fisiológico:","options":{"A":"Inibição da produção de inibinas pelo FSH, nas células da granulosa.","B":"Inibição da secreção de GnRH pela serotonina e peptídeos opioides endógenos.","C":"Início do crescimento folicular dependente de gonadotrofinas.","D":"Pico de LH coincidente com a oocitação."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-359431","number":"359431","sourceNumber":"359431","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente com 53 anos de idade, sem comorbidades, G3P3A0, menopausa aos 48 anos\nde idade, comparece à consulta ginecológica\nde rotina, assintomática. Hipertensa, obesidade grau\nIII e diabética com mau controle, faz uso de hidroclorotiazida, losartana, enalapril, metformina,\nsinvastatina e AAS. Ao exame físico sob esforço, observa-se descida de parede vaginal anterior até\n1cm acima do hímen. A conduta MAIS APROPRIADA para a paciente é:","options":{"A":"Colpocleise.","B":"Colporrafia anterior.","C":"Expectante.","D":"Pessário tipo Ring."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-330459","number":"330459","sourceNumber":"330459","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com a posição ereta do ser humano, desenvolveu-se o assoalho pélvico como\nestrutura de sustentação para evitar o\nprolapso dos órgão pélvicos. O equilíbrio entre arcabouço\nósseo e tecido fibromuscular permite a manutenção das funções orgânicas. Em relação à anatomia\ne fisiologia pélvicas na mulher, assinale a alternativa ERRADA:","options":{"A":"A função de suspensão do complexo uterovaginal, bexiga e reto é formada pelo tecido\nendopélvico e pela fáscia endopélvica","B":"As espinhas isquiáticas são estruturas exclusivas do ser humano","C":"O hiato urogenital é uma abertura central do assoalho pélvico que permite ocorrer funções\nfisiológicas como, coito, esvaziamento vesical e o parto","D":"O ligamento uterossacral é responsável pela suspensão lateral do colo uterino, surgindo na\nparede lateral pélvica e se inserindo lateralmente ao colo do útero"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-301195","number":"301195","sourceNumber":"301195","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ciclo reprodutivo feminino é controlado pelo eixo Hipotálamo-Hipófise-Ovário (HHO).\nSobre esse eixo, é CORRETO afirmar:","options":{"A":"A progesterona é o principal esteroide sexual responsável pelo feedback positivo no eixo\ngonadal, estimulando o pico do hormônio luteinizante (LH).","B":"Níveis circulantes altos e contínuos de estradiol, que ocorrem no final da fase folicular, são\nimportantes para o controle do eixo HHO e inibem (feedback negativo) a secreção do hormônio\nluteinizante (LH).","C":"O aumento inicial do estradiol que ocorre no início da fase folicular, exerce feedback negativo\nno\neixo hipotálamo-hipofisário, inibindo a secreção de hormônio folículo estimulante (FSH).","D":"O hormônio liberador de Gonadotrofina (GnRH) é produzido, principalmente, por neurônios\nlocalizados no hipotálamo mediobasal e secretado no sistema porta-hipofisário de maneira\ncontínua, modulando a liberação de gonadotrofinas."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-301196","number":"301196","sourceNumber":"301196","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O ciclo ovariano de mulheres e primatas superiores é denominado ciclo menstrual em\nvirtude da presença de menstruação, o que não ocorre em outras espécies. Sobre o ciclo menstrual\nfeminino é ERRADO afirmar:","options":{"A":"Durante o processo de desabamento menstrual, as camadas endometriais média (esponjosa) e\nsuperficial (compacta) são descamadas, permanecendo apenas a camada profunda (basal), que é\nresponsável pela renovação endometrial no próximo ciclo","B":"Em geral, a duração do ciclo menstrual reflete a duração da fase lútea, ou seja, ciclos curtos\nocorrem por fase lútea menor","C":"O ciclo menstrual de mulheres tem duração média de 28 dias, podendo variar de 21 a 35 dias,\ndivide-se em fase folicular, ovulação e fase lútea, sendo que a menstruação marca o início da fase\nfolicular","D":"Variação na duração do ciclo e na intensidade do fluxo menstrual são comuns nos extremos da\nvida reprodutiva"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-301197","number":"301197","sourceNumber":"301197","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"O manejo e diagnóstico de anormalidades do ciclo menstrual baseia-se na\ncompreensão dos mecanismos fisiológicos\nenvolvidos na regulação do ciclo menstrual normal.\nSobre esses mecanismos é ERRADO afirmar:","options":{"A":"A enzima aromatase converte androgênios em progesterona, processo que ocorre,\nprincipalmente, nas células da granulosa e estimulado pela ação do FSH","B":"A multiplicação das células germinativas começa por volta de 6 a 8 semanas de gravidez,\natingindo pico máximo entre 16 e 20 semanas de gestação","C":"O crescimento do folículo primordial e sua atresia é um processo contínuo, não sendo\ninterrompido em nenhuma circunstância\nfisiológica, incluindo gravidez, ovulação ou períodos de\nanovulação","D":"O início do desenvolvimento folicular envolve diversos mecanismos que são independentes das\ngonadotrofinas"},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-233766","number":"233766","sourceNumber":"233766","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 62 anos refere que há dois anos apresenta incontinência urinária ao esforço\ne por urgência, além de noctúria e\npolaciúria, com piora há 10 dias. Durante a consulta, relata\nimportante impacto negativo na sua qualidade de vida. A conduta inicial MAIS ADEQUADA nesse\nmomento é solicitar:","options":{"A":"Diário miccional.","B":"Estudo urodinâmico.","C":"Exame de urina rotina e urocultura.","D":"Fisioterapia do assoalho pélvico."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-255946","number":"255946","sourceNumber":"255946","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Dentre as técnicas cirúrgicas abaixo, assinale aquela que NÃO ESTÁ indicada para o\nrespectivo quadro:","options":{"A":"Cirurgia de Burch ? incontinência urinária de esforço","B":"Cirurgia de Donald-Fothergill ? prolapso uterino","C":"Cirurgia de Marshall-Marchetti-Krants ? retroversão uterina","D":"Cirurgia de Wertheim-Meigs ? câncer do colo uterino"},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-203280","number":"203280","sourceNumber":"203280","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Adolescente de 15 anos de idade chega à consulta com o ginecologista na Unidade\nBásica de Saúde com queixa de irregularidade\nmenstrual desde a menarca aos 13 anos e informa\nainda não ter iniciado a atividade sexual. Não apresenta outras queixas, mas informa que\nirregularidade menstrual a incomoda muito e que os ciclos menstruais têm intervalos de 20 a 45\ndias, com o fluxo variando de 3 a 10 dias. Sobre a fisiologia do ciclo menstrual dessa adolescente,\nassinale a alternativa CORRETA.","options":{"A":"A fase folicular é a que apresenta maior uniformidade nos ciclos, sendo que a lútea é a\nresponsável pela maior variação.","B":"A fase lútea é a mais uniforme, sendo que a variação na fase folicular justifica a irregularidade\nmenstrual.","C":"A irregularidade menstrual dessa adolescente está mais relacionada à capacidade de\nproliferação endometrial do que ao estímulo hormonal ovariano.","D":"Ambas as fases lútea e folicular são variáveis em igual proporção no ciclo menstrual."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-174616","number":"174616","sourceNumber":"174616","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Qual dos hormônios abaixo NÃO é produzido pelo corpo lúteo:","options":{"A":"Contractina.","B":"Inibina.","C":"Progesterona.","D":"Relaxina."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-174658","number":"174658","sourceNumber":"174658","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"A Incontinência Urinária de Esforço (IUE) é o tipo de perda de urina mais comum em\nmulheres, podendo o tratamento ser cirúrgico ou não cirúrgico. Em relação ao tratamento para a\nincontinência urinária de esforço, assinale a alternativa ERRADA:","options":{"A":"As intervenções no estilo de vida reduzem a ocorrência de IUE.","B":"O tratamento cirúrgico pode ser realizado com slings por via retropúbica ou transobturatória.","C":"Os exercícios da musculatura do assoalho pélvico não devem ser indicados como primeira linha\nde tratamento.","D":"Os pessários com suporte podem ser indicados como tratamento conservador."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-149943","number":"149943","sourceNumber":"149943","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação à fisiologia do ciclo menstrual normal, assinale a alternativa ERRADA:","options":{"A":"A inibina A é secretada pelo corpo lúteo.","B":"A variabilidade da fase folicular é responsável pelas alterações da duração total do ciclo.","C":"A variação dos níveis de progesterona após a ovulação contraindica sua dosagem como sinal\npresumido de ovulação.","D":"Os extremos da vida reprodutiva são caracterizados por ciclos anovulatórios e/ou irregulares."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-149873","number":"149873","sourceNumber":"149873","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Mulher de 58 anos, G5P4nA1, sexualmente ativa, última menstruação aos 51 anos,\nsem doenças prévias, não faz uso de terapia\nhormonal. Paciente relata perda de urina aos esforços\nhá três anos, com impacto na sua qualidade de vida. Sem outras queixas urinárias e com hábito\nintestinal regular. Ao exame clínico, apresenta prolapso de parede vaginal anterior estádio 1 pela\nclassificação do POP-Q e hipermobilidade uretral. Com relação ao tratamento indicado, assinale a\nalternativa ERRADA:","options":{"A":"A colporrafia anterior é o procedimento cirúrgico de escolha caso se opte pelo tratamento\ncirúrgico.","B":"As modificações do estilo de vida associado à terapia comportamental reduzem a incontinência\nurinária.","C":"Os exercícios com a musculatura do assoalho pélvico devem ser oferecidos como primeira linha\nde tratamento.","D":"Se não houver resposta ao tratamento conservador, deve-se oferecer tratamento cirúrgico."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-139686","number":"139686","sourceNumber":"139686","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Com relação ao ciclo menstrual fisiológico, pode-se afirmar que a(s) fase(s):","options":{"A":"Proliferativa é a mais constante e tem duração de 14 dias","B":"Progestogênica segue a fase estrogênica e tem duração variável","C":"Estrogênica costuma ter duração fixa, sendo a proliferativa variável em cada padrão de\nmenstruação","D":"Secretora costuma ter duração constante, variando a duração do ciclo em função da proliferativa"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-127476","number":"127476","sourceNumber":"127476","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Considerando as afirmativas abaixo relativas ao ciclo menstrual na mulher, assinale a\nalternativa ERRADA:","options":{"A":"Com a evolução do corpo lúteo, os níveis de Hormônio Folículo Estimulante (FSH) começam a\nse elevar e um grupo de folículos são\nrecrutados.","B":"Os folículos em crescimento produzem inibina B que suprime a secreção de FSH pela hipófise.","C":"A ovulação ocorre geralmente entre 24 a 36 horas após o pico do Hormônio Luteinizante (LH)\nhipofisário.","D":"A alteração dos níveis de progesterona pode ser usada como um sinal presuntivo se a ovulação\nocorreu ou não."},"answer":"B","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-78436","number":"78436","sourceNumber":"78436","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 56 anos, G3 P3 (três partos vaginais), queixa-se de \"bola saindo pela\nvagina\" quando faz esforços. Nega sangramento\nou outros sintomas locais. Menopausa há cinco\nanos e nunca fez terapia hormonal. Refere ainda tosse crônica relacionada ao cigarro (SIC). Estado\ngeral preservado, paciente aparentemente hígida. Antes mesmo de realizar o exame clínico você\nimagina os quadros mais prováveis para justificar a queixa da paciente. Assinale a alternativa\nERRADA, baseando-se na hipótese ou hipóteses mais prováveis:","options":{"A":"É provável que a paciente apresente um tumor do colo do útero.","B":"Na maioria das vezes, esses quadros são passíveis de tratamento cirúrgico por via vaginal.","C":"Esses casos podem apresentar associação a sintomas urinários e, então, a paciente deve ser\nquestionada sobre dificuldade miccional ou perda involuntária de urina.","D":"Partos vaginais, tosse crônica e sedentarismo são fatores envolvidos no desenvolvimento desse\nquadro clínico."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-78356","number":"78356","sourceNumber":"78356","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"ATF, 42 anos, queixa-se de perda urinária em pequenas quantidades sempre que faz\nalgum esforço, como levantar peso, levantar rapidamente de uma cadeira e também durante tosse.\nG2P2 (duas cesáreas). Nega outras doenças. Nega uso de medicamentos por outros problemas de\nsaúde. Baseado nessa história, foram solicitados exames de urina, teste de esforço e estudo\nurodinâmico. Baseado nos resultados que você espera encontrar, assinale a alternativa ERRADA:","options":{"A":"É provável que o exame de urina de rotina e urocultura sejam normais, pois não há queixa\nsugestiva de infecção urinária.","B":"O exame de Urodinâmica deverá revelar complacência vesical, volume residual e fluxo de\nesvaziamento normais.","C":"O teste de esforço deverá ser positivo, comprovando a perda urinária.","D":"O exame urodinâmico deverá registrar contrações não inibidas do músculo detrusor."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-78389","number":"78389","sourceNumber":"78389","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Na figura abaixo (VER IMAGEM) vemos a sutura de aproximação da musculatura numa\ncirurgia de correção de rotura perineal (perineoplastia). Entre os músculos abaixo, assinale a opção\nCORRETA do principal músculo que sempre estará envolvido nessa sutura:","options":{"A":"Músculo pubococcígeo.","B":"Músculo transverso superficial do períneo.","C":"Músculo isquiocavernoso.","D":"Músculo esfíncter anal externo."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-60312","number":"60312","sourceNumber":"60312","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Em relação ao ciclo menstrual fisiológico, assinalar a alternativa ERRADA:","options":{"A":"A formação do corpo lúteo só acontecerá se ocorrer a fecundação do óvulo.","B":"A síntese de progesterona na fase lútea tem como objetivo o preparo endometrial para a\nnidação.","C":"Na fase periovulatória ocorre o término da maturação do óvulo.","D":"Nos primeiros sete dias da fase folicular ocorre o recrutamento e a seleção do folículo\ndominante."},"answer":"A","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-45160","number":"45160","sourceNumber":"45160","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 60 anos de idade, G1P1A0, com relato de \"perda de urina\" e algumas\nvezes sentir \"muita vontade de urinar e ao\nchegar ao banheiro, urina pouco\". Sem alterações ao\nexame clínico ginecológico. Exame de urina normal. Estudo urodinâmico evidenciou fase de\nenchimento normal com perda, fase de esvaziamento normal e ausência de contrações não\ninibidas. Com base nesses achados, o diagnóstico mais provável é de:","options":{"A":"Bexiga hiperativa.","B":"Bexiga neurogênica hipotônica.","C":"Incontinência urinária de esforço.","D":"Incontinência urinária mista."},"answer":"C","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-53344","number":"53344","sourceNumber":"53344","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente 72 anos, G6P6A0 (6 partos vaginais) com queixa de urgência miccional,\nfrequência urinária aumentada (10 micções/dia) e\nnoctúria. Nega perda urinária aos esforços.\nExame clínico sem evidências de prolapso genital. Urodinâmica mostrou presença de contrações\nnão inibidas do detrusor e ausência de incontinência urinária aos esforços. São condutas\napropriadas para a paciente, EXCETO:","options":{"A":"Anticolinérgicos","B":"Antidepressivo tricíclico","C":"Fisioterapia","D":"Tratamento cirúrgico"},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-52351","number":"52351","sourceNumber":"52351","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Paciente de 56 anos, G2P2A0 (2PN), com queixa de frequência urinária aumentada (9\nmicções/dia), urgência miccional, urgeincontinência e noctúria. Nega perda urinária aos esforços.\nInforma restrição de suas atividades cotidianas devido à perda urinária. Ao exame clínico, sem\nevidências de prolapso genital. Urodinâmica mostrou presença de contrações não inibidas do\ndetrusor e ausência de perda urinária aos esforços. São condutas apropriadas para a paciente,\nEXCETO:","options":{"A":"Fisioterapia.","B":"Antidepressivo tricíclico.","C":"Anticolinérgicos.","D":"Tratamento cirúrgico."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-03-52365","number":"52365","sourceNumber":"52365","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-03","collectionLabel":"MED · MED GIN 03","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 03","subtopic":"","stem":"Dentre os benefícios não contraceptivos dos anticoncepcionais orais combinados,\npodemos citar, EXCETO:","options":{"A":"Diminuição do fluxo menstrual.","B":"Diminuição do risco de câncer de endométrio.","C":"Diminuição do risco de câncer de ovário.","D":"Diminuição do volume uterino."},"answer":"D","source":"Gineco e obstetricia/MED GIN 03/MED GIN 03.txt","sourceLabel":"MED · MED GIN 03","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 03","MED"],"answerSource":"explicit","commentDeferred":true}]};
